const cfg = $('Config').first().json;
const raw = cfg.body || {};
const errors = [];
if (!raw.id) errors.push('missing id');
if (!raw.title) errors.push('missing title');
if (!raw.description && !raw.logs) errors.push('missing description and logs');
if (raw.timestamp && isNaN(Date.parse(raw.timestamp))) errors.push('bad timestamp');
const text = [raw.title, raw.description, raw.logs].filter(Boolean).join('\n');
return [{ json: { incident_id: $input.first().json.id, raw, valid: errors.length === 0, errors, text } }];

