parameters.jsCode:
const d = $input.first().json;
const rules = [
  ['database', /deadlock|connection pool|too many connections|replication lag|slow quer/i],
  ['disk_storage', /no space left|disk (usage )?9\d%|inode/i],
  ['memory', /\boom\b|oomkilled|out of memory|heap/i],
  ['network', /\b50[234]\b|timed? ?out|dns|enotfound/i],
  ['certificate', /ssl|tls|certificate|expired/i],
  ['deployment', /deploy|rollback|release failed|rollout/i],
  ['auth', /\b40[13]\b|invalid token|login failed|token expired/i],
  ['cpu', /cpu (at )?9\d%|high load|load average/i],
];
const hit = rules.find(([, re]) => re.test(d.text));
const rule_severity = /outage|down|prod|critical|data loss/i.test(d.text) ? 'high' : 'medium';
const classify_prompt =
  'You are an IT incident triage assistant. Classify the incident using ONLY the text below.\n' +
  'type must be one of: database, disk_storage, memory, network, certificate, deployment, auth, cpu, unknown (use unknown if none clearly fits).\n' +
  'severity must be one of: low, medium, high, critical.\n' +
  'confidence is a number from 0 to 1; lower it when the text is ambiguous.\n' +
  'evidence is up to 3 EXACT quotes copied from the text. Do not invent details.\n\n' +
  'INCIDENT:\n' + d.text;
return [{ json: { ...d, rule_type: hit ? hit[0] : 'unknown', rule_severity, classify_prompt } }];

const cfg = $('Config').first().json;
const base = $('Rules').first().json;
const TYPES = ['database','disk_storage','memory','network','certificate','deployment','auth','cpu','unknown'];
const SEVS = ['low','medium','high','critical'];
const norm = s => String(s).replace(/\s+/g, ' ').trim();
let c = null, method = 'llm';
if (cfg.LLM_MODE === 'mock') {
  c = { type: base.rule_type, severity: base.rule_severity, confidence: 0.7, evidence: [] };
  method = 'mock';
} else {
  try {
    const txt = $input.first().json.candidates[0].content.parts[0].text;
    const p = JSON.parse(txt);
    if (TYPES.includes(p.type) && SEVS.includes(p.severity) && typeof p.confidence === 'number' && Array.isArray(p.evidence)) c = p;
  } catch (e) {}
  if (!c) {
    c = { type: base.rule_type, severity: base.rule_severity, confidence: 0.4, evidence: [] };
    method = 'rules_fallback';
  }
}
// keep only evidence that really appears in the incident text
const haystack = norm(base.text);
const evidence = (c.evidence || []).filter(e => typeof e === 'string' && haystack.includes(norm(e)));
const confidence = Math.round(Math.min(1, Math.max(0, Number(c.confidence))) * 100) / 100;
const reasons = [];
if (confidence < cfg.CONF_THRESHOLD) reasons.push('low_confidence');
if (c.type === 'unknown') reasons.push('unknown_type');
if (method === 'rules_fallback') reasons.push('llm_failed_used_rules');
if (method === 'llm' && evidence.length === 0) reasons.push('no_verified_evidence');
if (method === 'llm' && base.rule_type !== 'unknown' && c.type !== base.rule_type) reasons.push('llm_rules_disagree');
const model = method === 'llm' ? cfg.GEN_MODEL : method;
return [{ json: {
  incident_id: base.incident_id, text: base.text,
  type: c.type, severity: c.severity, confidence, evidence, method, model,
  needs_review: reasons.length > 0, review_reasons: reasons
}}];

