const cfg = $('Config').first().json;
const p = $('Parse Classification').first().json;
const rows = $input.all().map(i => i.json);
const passing = r => Number(r.score) >= cfg.MIN_SCORE;
const runbooks = rows.filter(r => r.kind === 'runbook' && passing(r)).slice(0, 3);
const past = rows.filter(r => r.kind === 'past' && passing(r)).slice(0, 2);
const no_source = runbooks.length === 0;
const actions = no_source ? [] : rows.filter(r => r.kind === 'actions');
const best_score = Math.max(0, ...rows.filter(r => r.score !== null && r.score !== undefined).map(r => Number(r.score)));
const reasons = [...p.review_reasons];
if (no_source) reasons.push('no_source_found');
const excerpts = [...runbooks, ...actions].map((r, i) => '[Runbook] ' + r.title + '\n' + r.text).join('\n\n');
const pastText = past.map(r => '[Past incident] ' + r.title + '\n' + r.text).join('\n\n');
const plan_prompt =
  'You help an IT engineer troubleshoot. Use ONLY the excerpts below.\n' +
  'Return a troubleshooting plan of at most 6 steps. Each step has: step (short action), detail (one sentence), source (the EXACT title of the runbook or past incident it came from).\n' +
  'Steps are suggestions for a human engineer. Never propose automatic production changes; anything risky must say it needs human approval.\n' +
  'If the excerpts do not cover the problem, return fewer steps. Do not invent steps.\n\n' +
  'INCIDENT:\n' + p.text + '\n\nCLASSIFIED AS: ' + p.type + ' / ' + p.severity + '\n\n' +
  'EXCERPTS:\n' + excerpts + '\n\n' + pastText;
return [{ json: {
  ...p, runbooks, past, actions, no_source, best_score,
  review_reasons: reasons, needs_review: p.needs_review || no_source,
  call_llm: !no_source && cfg.LLM_MODE === 'live', plan_prompt
}}];

const d = $('Collect Sources').first().json;
const resp = $input.first().json;

const titles = [
  ...d.runbooks.map(r => r.title),
  ...d.past.map(r => r.title)
];

const normalizeTitle = (value) =>
  String(value || '')
    .replace(/^\[[^\]]*\]\s*/, '')
    .replace(/^(runbook|past incident)\s*:\s*/i, '')
    .trim();

const validTitles = new Set(titles.map(normalizeTitle));
const reasons = [...d.review_reasons];

let plan = [];
let plan_method = 'none';

if (d.call_llm) {
  try {
    const arr = JSON.parse(
      resp.candidates[0].content.parts[0].text
    );

    if (Array.isArray(arr)) {
      plan = arr
        .map(s => ({
          step: String(s?.step || '').trim(),
          detail: String(s?.detail || '').trim(),
          source: normalizeTitle(s?.source)
        }))
        .filter(s =>
          s.step &&
          s.detail &&
          validTitles.has(s.source)
        )
        .slice(0, 6);
    }

    if (plan.length) {
      plan_method = 'llm';
    }
  } catch (e) {
    // Invalid or unexpected Gemini response; use fallback below.
  }
}

if (!plan.length && !d.no_source) {
  // Extractive fallback: Recommended Actions bullets from retrieved runbooks.
  for (const r of d.actions || []) {
    const bullets = String(r.text || '')
      .split('\n')
      .filter(line => line.startsWith('- '));

    for (const line of bullets) {
      plan.push({
        step: line.slice(2).trim(),
        detail: '',
        source: r.title
      });
    }
  }

  plan = plan.slice(0, 6);

  if (plan.length) {
    plan_method = d.call_llm
      ? 'extractive_fallback'
      : 'extractive';
  }

  if (d.call_llm && plan.length && !reasons.includes('plan_llm_failed')) {
    reasons.push('plan_llm_failed');
  }
}

const seen = {};

[
  ...d.runbooks.map(r => ({
    kind: 'runbook',
    title: r.title,
    score: Number(r.score)
  })),
  ...d.past.map(r => ({
    kind: 'past_incident',
    title: r.title,
    score: Number(r.score)
  }))
].forEach(s => {
  const key = s.kind + '|' + s.title;

  if (!seen[key] || s.score > seen[key].score) {
    seen[key] = s;
  }
});

const sources = Object.values(seen);

const needs_review =
  d.needs_review ||
  reasons.includes('plan_llm_failed');

return [{
  json: {
    incident_id: d.incident_id,
    type: d.type,
    severity: d.severity,
    confidence: d.confidence,
    method: d.method,
    plan,
    plan_method,
    sources,
    review_reasons: reasons,
    needs_review,
    status: needs_review ? 'needs_review' : 'planned',
    best_score: d.best_score
  }
}];

